import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"命令行搜索（lff）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/cli.md","filePath":"zh-CN/user-guide/cli.md","lastUpdated":1785993908000}'),d={name:"zh-CN/user-guide/cli.md"};function l(p,a,o,r,n,h){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="命令行搜索-lff" tabindex="-1">命令行搜索（lff） <a class="header-anchor" href="#命令行搜索-lff" aria-label="Permalink to &quot;命令行搜索（lff）&quot;">​</a></h1><p>Lertaro 还附带一个小巧的命令行伴侣工具 <strong><code>lff</code></strong>——一个 fzf 风格的模糊查找器，检索的是 App 本身已经维护好的同一份索引，而不是自己再重新扫描一遍。它是给那些常年待在终端里、也希望能用上 Lertaro 那套搜索能力（模糊匹配、拼音别名、网络盘，一应俱全）的人准备的，不只是局限在搜索窗口里。</p><p><code>lff</code> 需要 Lertaro App 已经在运行——它是通过一条本地的、按用户区分的管道跟 App 通信，而不是自己重新扫一遍。如果 App 没有运行，<code>lff</code> 会快速失败，把错误信息输出到 stderr，而不是卡住不动。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p><code>lff.exe</code> 会和 App 一起安装。在安装程序的任务选择页面勾选<strong>将 lff 命令行搜索工具添加到 PATH</strong>，就能在任意终端里直接以 <code>lff</code> 运行——这一步会把 Lertaro 的安装目录加进系统 PATH。勾选之后请重新打开一个终端窗口；安装时已经开着的那个不会自动感知到这个变化。</p><p>如果安装时跳过了这个选项，仍然可以直接从 Lertaro 的安装目录里运行它。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff</span></span></code></pre></div><p>会打开一个交互式选择界面：打字即可模糊过滤，跟 App 自己的搜索完全一致——包括中文文件名的拼音别名匹配（参见<a href="./search-syntax.html">搜索语法</a>）。</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td>打字</td><td>过滤结果</td></tr><tr><td>↑ / ↓</td><td>移动高亮项</td></tr><tr><td>Page Up / Page Down</td><td>翻页</td></tr><tr><td>← / →</td><td>移动查询文本中的光标</td></tr><tr><td>Tab</td><td>切换选中/取消选中当前高亮的结果（选中的行会显示 <code>*</code>）</td></tr><tr><td>Enter</td><td>输出选中的路径——如果没有选中任何项，就输出当前高亮的那一个——然后退出</td></tr><tr><td>Esc / Ctrl+C</td><td>不输出任何内容，直接退出</td></tr></tbody></table><h2 id="预填充查询关键字" tabindex="-1">预填充查询关键字 <a class="header-anchor" href="#预填充查询关键字" aria-label="Permalink to &quot;预填充查询关键字&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff report</span></span></code></pre></div><p>以及</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo report | lff</span></span></code></pre></div><p>两种方式都会以 <code>report</code> 作为初始关键字打开界面并直接过滤。不管哪种方式，这都只是预填充查询框、然后像手动打字一样触发同一次搜索——它自己不会做任何自动选择或自动输出，你仍然需要自己导航、按 Enter/Tab 确认。</p><h2 id="多选结果" tabindex="-1">多选结果 <a class="header-anchor" href="#多选结果" aria-label="Permalink to &quot;多选结果&quot;">​</a></h2><p>Tab 用来标记/取消标记当前高亮的这一行。标记状态会在你改变查询关键字之后依然保留——所以你可以先搜一个文件标记它，再搜别的文件继续标记，以此类推。状态栏会显示当前一共标记了几项。只要有标记项，按 Enter 就会输出所有被标记的路径（每行一个），跟当前高亮的是哪一项无关。</p><h2 id="把结果用到别的命令里" tabindex="-1">把结果用到别的命令里 <a class="header-anchor" href="#把结果用到别的命令里" aria-label="Permalink to &quot;把结果用到别的命令里&quot;">​</a></h2><p><code>lff</code> 的交互界面是直接画在控制台上的，完全不经过标准输入输出流——唯一会真正写进 stdout 的，只有按 Enter 时输出的那些最终选中路径（每行一个）。这也是它能跟常见 shell 技巧组合、把结果传给别的命令的原因。</p><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; code $path</span></span></code></pre></div><p>cmd.exe（没有内置的命令替换语法，用 <code>for /f</code>）：</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="局限" tabindex="-1">局限 <a class="header-anchor" href="#局限" aria-label="Permalink to &quot;局限&quot;">​</a></h2><ul><li>没有预览面板——这是有意为之的取舍，App 自己的<a href="./actions-and-preview.html">动作菜单与预览</a>已经覆盖了这部分需求。</li><li>需要 Lertaro App 正在运行；<code>lff</code> 自己不会索引任何东西。</li></ul>`,25)])])}const u=t(d,[["render",l]]);export{f as __pageData,u as default};
